<?php
require_once __DIR__.'/includes/init.php'; require_login(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
 try { if(strlen($new)<10 || strlen($new)>200) throw new InvalidArgumentException('Password baru minimal 10 karakter.'); if($new!==$confirm) throw new InvalidArgumentException('Konfirmasi password tidak sama.'); $s=db_login()->prepare('SELECT password FROM tb_user WHERE id_user=?');$s->execute([current_user()['id']]);$row=$s->fetch();if(!$row||!password_verify($old,(string)$row['password']))throw new InvalidArgumentException('Password lama tidak sesuai.');$u=db_login()->prepare('UPDATE tb_user SET password=? WHERE id_user=?');$u->execute([password_hash($new,PASSWORD_DEFAULT),current_user()['id']]);$log=db_login()->prepare('INSERT INTO tb_log_aktivitas(id_user,aktivitas) VALUES(?,?)');$log->execute([current_user()['id'],'Mengubah password sendiri']);flash('success','Password berhasil diubah.');redirect('change-password.php');}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Password belum dapat diubah.';if(!$e instanceof InvalidArgumentException)error_log('[ParkirSTRD password] '.$e->getMessage());}
}
require_once __DIR__.'/includes/layout.php';render_header('Ubah Password','');?><div class="content-narrow"><section class="panel"><div class="panel-heading"><div><h2>Keamanan akun</h2><p>Gunakan password unik dengan panjang minimal 10 karakter.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><form method="post" class="form-grid single-col"><?= csrf_field() ?><div class="field"><label>Password lama</label><input type="password" name="old_password" required autocomplete="current-password"></div><div class="field"><label>Password baru</label><input type="password" name="new_password" minlength="10" required autocomplete="new-password"></div><div class="field"><label>Konfirmasi password baru</label><input type="password" name="confirm_password" minlength="10" required autocomplete="new-password"></div><div class="form-actions"><button class="btn btn-primary">Simpan perubahan</button></div></form></section></div><?php render_footer();